test('phase proof rejects stale accounting, expired clock, and unresolved transport; restart retains clock',async()=>{
 const dir=await mkdtemp(resolve(tmpdir(),'openlearn-phase-negative-')),priorStorePath=resolve(dir,'prior.sqlite');priorFixture(priorStorePath);const priorAccounting=readNavigationAccounting(priorStorePath);let clock=100000,paid=0;
 const make=(path,transport)=>createOpenLearnPipelineBudget({storePath:path,priorStorePath,priorAccounting,catalogs,now:()=>clock,fetch:transport??(async(_url,init)=>{paid++;return Response.json({id:'synthetic-'+paid,model:JSON.parse(init.body).model,usage:{prompt_tokens:2,completion_tokens:2,cost:0.000001}});})});
 let budget=make(resolve(dir,'new.sqlite'));
 const proof=async(accounting)=>{const resultPath=resolve(dir,'result.json'),tracePath=resolve(dir,'trace.jsonl'),recordedAt=new Date(clock).toISOString();await writeFile(resultPath,JSON.stringify({version:'openlearn-six-page-pipeline-result-v1',recordedAt,cleanup:{ok:true},accounting}));await writeFile(tracePath,JSON.stringify({at:recordedAt,phase:'pipeline-stopped',cleanup:{ok:true},accounting})+'\n');return {resultPath,resultSha256:hash(await readFile(resultPath)),tracePath,traceSha256:hash(await readFile(tracePath))};};
 try{
  await budget.modelFetch('https://openrouter.ai/api/v1/chat/completions',request());const original=budget.snapshot();budget.close();budget=make(resolve(dir,'new.sqlite'));assert.equal(budget.snapshot().current.startedAtMs,original.current.startedAtMs);
  await budget.modelFetch('https://openrouter.ai/api/v1/chat/completions',request());assert.throws(()=>budget.pauseForPreparation({resultPath:'missing',resultSha256:'0',tracePath:'missing',traceSha256:'0'}));const stale=await proof(original);assert.throws(()=>budget.pauseForPreparation(stale),/ProofInvalid/);assert.equal(budget.snapshot().preparationPaused,false);
  clock+=1800001;const expired=await proof(budget.snapshot());assert.throws(()=>budget.pauseForPreparation(expired),/PauseInvalid/);await assert.rejects(budget.modelFetch('https://openrouter.ai/api/v1/chat/completions',request()),/DeadlineExceeded/);assert.equal(paid,2);budget.close();
  budget=make(resolve(dir,'unknown.sqlite'),async()=>{paid++;throw Error('SYNTHETIC_TRANSPORT_FAILURE');});await assert.rejects(budget.modelFetch('https://openrouter.ai/api/v1/chat/completions',request()),error=>error instanceof AgentExecutionBoundaryFailure&&error.failure.kind==='PipelineModelTransportFailed'&&error.failure.field==='dispatch'&&error.notStarted===false);const uncertain=budget.snapshot();assert.equal(uncertain.current.unresolvedRequests,1);assert.equal(uncertain.current.halted,'EvaluationTransportUncertain');assert.throws(()=>budget.pauseForPreparation({resultPath:'missing',resultSha256:'0',tracePath:'missing',traceSha256:'0'}));await assert.rejects(budget.modelFetch('https://openrouter.ai/api/v1/chat/completions',request()),/AccountingHalted/);assert.equal(paid,3);
 }finally{budget.close();await rm(dir,{recursive:true,force:true});}
});

