test('explicit extra reviewer attempt preserves three failures and cannot authorize a fifth',async()=>{
 const db=new DatabaseSync(':memory:');try{
  await migrations(db);const database=createD1Port(db),logger=()=>{};await seedIsolatedPreferences({db,database,ownerId:'owner',sourceUrl:root,preferences:{lessOften:[]},now,logger});
  const scope={ownerId:'owner',runId:'isolated-preference-fixture'},repository=new D1WorkflowStageRepository({database,now}),digest='exact-input',key='question-evaluator:extra-review',proof='d'.repeat(64);let current=key;
  for(let i=0;i<3;i++){db.prepare("INSERT INTO knowledge_workflow_stages(owner_id,run_id,stage_key,input_digest,status,created_at) VALUES(?,?,?,?,'claimed',?)").run(scope.ownerId,scope.runId,current,digest,now());if(i<2)current+=':owner-review-recovery:'+proof;}
  const historical=db.prepare('SELECT * FROM knowledge_workflow_stages ORDER BY stage_key').all(),terminal=current;let calls=0;
  const options={modelCall:true,maximumProviderAttempts:3,recoverFailedModel:async identity=>({attemptKey:proof,...(identity.key===terminal?{allowAdditionalAttempt:true}:{})})};
  const success=await repository.run(scope,key,digest,async()=>{calls++;return {ok:true,value:{synthetic:true}};},options);assert.equal(success.ok,true);assert.equal(calls,1);
  assert.deepEqual(await repository.run(scope,key,digest,()=>assert.fail('Cached fourth success must not call again'),options),success);
  for(const row of historical)assert.deepEqual(db.prepare('SELECT * FROM knowledge_workflow_stages WHERE stage_key=?').get(row.stage_key),row);
  const fourth=terminal+':owner-review-recovery:'+proof;db.prepare("UPDATE knowledge_workflow_stages SET status='claimed',result_json=NULL,completed_at=NULL WHERE stage_key=?").run(fourth);
  assert.equal((await repository.run(scope,key,digest,()=>assert.fail('Fifth attempt forbidden'),{...options,recoverFailedModel:async()=>({attemptKey:proof,allowAdditionalAttempt:true})})).error.kind,'WorkflowStageProviderRetryLimitReached');
 }finally{db.close();}
});


