test('finite continuation deadline grant appends once without changing original start or counters',async()=>{
 const db=new DatabaseSync(':memory:');try{
  const run={ownerId:'owner',runId:'run',revision:25,state:'retryable-failure',extractionStartedAt:now(),extractionDeadlineAt:'2026-10-13T00:30:00.000Z',counts:{pages:3,knowledgePoints:6}},authority={version:'owner-full-reserve-continuation-v1',ownerAuthorized:true,additionalMilliseconds:1800000,identity:{ownerId:'owner',runId:'run'}};let writes=0;
  const repository={update:async c=>{writes++;assert.equal(c.expectedRevision,25);return {ok:true,value:c.next};}},args={db,repository,run,authority,authorizationSha256:'a'.repeat(64),now};
  const next=await extendContinuationDeadline(args);assert.equal(next.extractionDeadlineAt,'2026-10-13T01:00:00.000Z');assert.equal(next.extractionStartedAt,run.extractionStartedAt);assert.deepEqual(next.counts,run.counts);
  assert.deepEqual(await extendContinuationDeadline({...args,run:next}),next);assert.equal(writes,1);
  await assert.rejects(extendContinuationDeadline({...args,authority:{...authority,additionalMilliseconds:3600000},authorizationSha256:'b'.repeat(64)}),/Unauthorized/);
 }finally{db.close();}
});

