 const db=new DatabaseSync(':memory:');await migrations(db);const database=createD1Port(db),repository=new D1KnowledgeWorkflowRepository({database,logger:()=>{}}),service=createKnowledgeWorkflowService(repository,{now,createId:()=> 'historical-recovery-run',logger:()=>{}}),identity={ownerId:'historical-owner',runId:'historical-recovery-run',stageKey:'knowledge-scraper:scraper-plan:sha256:'+'1'.repeat(64),inputDigest:'sha256:'+'1'.repeat(64),createdAt:now()};
