 db.prepare("INSERT INTO knowledge_workflow_stages(owner_id,run_id,stage_key,input_digest,status,created_at) VALUES(?,?,?,?,'claimed',?)").run(identity.ownerId,identity.runId,identity.stageKey,identity.inputDigest,identity.createdAt);
 const authorizationSha256='8'.repeat(64),attemptKey=hash(JSON.stringify({authorizationSha256,identity})),proof={reservationKey:'older-closed-404-fixture',retainedReservationNanodollars:30154752,authorizationSha256,identity,attemptKey,maximumAdditionalAttempts:1},childKey=identity.stageKey+':owner-model-recovery:'+attemptKey,value={ok:true,value:{cachedPlan:'actual-persisted-stage-fixture'}};
 db.prepare("INSERT INTO knowledge_workflow_stages(owner_id,run_id,stage_key,input_digest,status,result_json,created_at,completed_at) VALUES(?,?,?,?,'completed',?,?,?)").run(identity.ownerId,identity.runId,childKey,identity.inputDigest,JSON.stringify(value),now(),now());
 const priorRows=db.prepare('SELECT * FROM knowledge_workflow_stages ORDER BY stage_key').all();let authorizations=0;
 // The public budget proof represents an older authenticated journal while a
 // later authorization concerns another stage. It is not a model response.
 const budget={latestOwnerRecovery:{authorizationSha256:'9'.repeat(64),identity:{...identity,stageKey:'knowledge-scraper:later-unrelated'}},bindModelStage:()=>{},authorizeReviewStageRecovery:()=>assert.fail('Scraper recovery must not use reviewer assumptions'),authorizeScraperStageRecovery:async stage=>{authorizations++;if(!Object.keys(identity).every(k=>stage[k]===identity[k]))return null;assert.equal(stage.status,'claimed');assert.equal(stage.result_json,null);assert.equal(stage.completedAt,null);return proof;}},hooks=createFailedReviewRecoveryHooks({db,budget,identity}),stages=new D1WorkflowStageRepository({database,now,logger:()=>{}});
 return {db,identity,proof,childKey,value,priorRows,budget,hooks,stages,authorizations:()=>authorizations};
